mapper.select:
SELECT id FROM tc_operation_audit
  WHERE tenant_id=#{tenant} AND resource_type='REFUND' AND resource_id=#{resource} AND action=#{action}
  ORDER BY id DESC LIMIT 1

SELECT * FROM ( (SELECT CONCAT('E',a.id) AS id,r.request_id,COALESCE(a.audit_trace_id,r.trace_id) AS trace_id, a.action,a.actor_key AS actor_id,a.resource_id,a.created_at AS occurred_at,'SUCCEEDED' AS result, NULL AS error_code,CAST(a.id AS CHAR) AS effect_id,a.before_version,a.after_version, a.audit_order_ref AS order_no,a.audit_refund_display_no AS business_no,CAST(a.audit_amount_minor AS CHAR) AS amount_minor, a.audit_currency AS currency,a.audit_before_state AS before_state,a.audit_after_state AS after_state FROM tc_operation_audit a LEFT JOIN tc_audit_operation_attempt r ON r.tenant_id=a.tenant_id AND r.id=a.audit_attempt_id WHERE a.tenant_id=#{tenant} AND a.resource_type='REFUND' AND a.resource_id=#{resource}
AND (a.created_at < #{before} OR (a.created_at=#{before} AND CONCAT('E',a.id) < #{cursor}))
ORDER BY occurred_at DESC,id DESC LIMIT #{limit}) UNION ALL (SELECT CONCAT('R',o.id) AS id,r.request_id,r.trace_id,r.action_code AS action,r.actor_key AS actor_id, o.resource_id,r.occurred_at,o.result_code AS result,o.error_code,CAST(o.effect_id AS CHAR) AS effect_id, NULL AS before_version,NULL AS after_version,NULL AS order_no,NULL AS business_no,NULL AS amount_minor, NULL AS currency,NULL AS before_state,NULL AS after_state FROM tc_audit_attempt_outcome o JOIN tc_audit_operation_attempt r ON r.tenant_id=o.tenant_id AND r.id=o.attempt_id WHERE o.tenant_id=#{tenant} AND o.resource_id=#{resource} AND r.action_code <> 'refund.audit.list'
AND (r.occurred_at < #{before} OR (r.occurred_at=#{before} AND CONCAT('R',o.id) < #{cursor}))
ORDER BY occurred_at DESC,id DESC LIMIT #{limit}) ) evidence ORDER BY occurred_at DESC,id DESC LIMIT #{limit}
